from __future__ import annotations


class Group:
    def __init__(self, members: list[str]) -> None:
        # preserve order, drop exact duplicates while keeping first occurrence
        self._members: list[str] = []
        for m in members:
            if m not in self._members:
                self._members.append(m)
        self._net: dict[str, float] = {m: 0.0 for m in self._members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if payer not in self._net:
            raise ValueError(f"Unknown payer: {payer!r}")
        if amount <= 0:
            raise ValueError("Amount must be positive")

        if participants is None:
            participants = list(self._members)
        else:
            # validate all participants first
            for p in participants:
                if p not in self._net:
                    raise ValueError(f"Unknown participant: {p!r}")

        # total in cents to avoid float drift
        total_cents = round(amount * 100)
        if total_cents <= 0:
            raise ValueError("Amount must be positive")

        if len(participants) == 0:
            # nothing to split; payer just gets paid back? No one to charge.
            # Treat as error since no participants means no split possible.
            raise ValueError("At least one participant required")

        n = len(participants)
        share_cents = total_cents // n  # floored equal share

        # everyone except payer in participants owes share_cents
        # payer's own share (if in participants) is borne by payer directly;
        # leftover cents are borne by the payer.
        #
        # Net logic: payer paid `total_cents`. Each participant (other than
        # payer) owes share_cents to the payer (positive for payer, negative
        # for them). If payer is a participant, their own share is their own
        # cost, so it nets out. Any leftover cents remain with the payer
        # (i.e., payer effectively pays more, borne by payer).

        self._net[payer] += amount  # full amount paid

        # determine each participant's personal cost
        # Everyone pays share_cents; the payer additionally bears leftover.
        # So: payer cost = share_cents (if participant) + leftover
        #     other participant cost = share_cents
        leftover_cents = total_cents - share_cents * n

        for p in participants:
            cost_cents = share_cents
            if p == payer:
                cost_cents += leftover_cents
            self._net[p] -= cost_cents / 100.0

        # round each balance to cents to keep consistency
        for k in self._net:
            self._net[k] = round(self._net[k], 2)

    def balances(self) -> dict[str, float]:
        return {m: round(v, 2) for m, v in self._net.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # work in cents
        creditors: list[list] = []  # [name, cents_owed]
        debtors: list[list] = []    # [name, cents_debt]

        for name, bal in self._net.items():
            cents = round(bal * 100)
            if cents > 0:
                creditors.append([name, cents])
            elif cents < 0:
                debtors.append([name, -cents])

        # sort for deterministic output
        creditors.sort(key=lambda x: (-x[1], x[0]))
        debtors.sort(key=lambda x: (-x[1], x[0]))

        payments: list[tuple[str, str, float]] = []

        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor_name, debt = debtors[i]
            creditor_name, credit = creditors[j]
            pay = min(debt, credit)
            payments.append((debtor_name, creditor_name, pay / 100.0))
            debt -= pay
            credit -= pay
            debtors[i][1] = debt
            creditors[j][1] = credit
            if debt == 0:
                i += 1
            if credit == 0:
                j += 1

        # write off any remaining debts/credits below 1.00
        result: list[tuple[str, str, float]] = []
        for d, c, amt in payments:
            if amt >= 1.00:
                result.append((d, c, round(amt, 2)))
        return result
